import{_ as n,o as h,c as i,a2 as r}from"./chunks/framework.BBd5PKnH.js";const l=JSON.parse('{"title":"Thần hành tinh, ý nghĩa theo Valens và archetype hiện đại","description":"","frontmatter":{},"headers":[],"relativePath":"astro/planets/classification/deities-n-valens.md","filePath":"astro/planets/classification/deities-n-valens.md"}'),a={name:"astro/planets/classification/deities-n-valens.md"};function o(g,t,c,e,d,s){return h(),i("div",null,[...t[0]||(t[0]=[r('<h1 id="than-hanh-tinh-y-nghia-theo-valens-va-archetype-hien-đai" tabindex="-1">Thần hành tinh, ý nghĩa theo Valens và archetype hiện đại <a class="header-anchor" href="#than-hanh-tinh-y-nghia-theo-valens-va-archetype-hien-đai" aria-label="Permalink to &quot;Thần hành tinh, ý nghĩa theo Valens và archetype hiện đại&quot;">​</a></h1><p><em>(Demetra George, Ancient Astrology in Theory and Practice, Vol. I, Chương 3, Table 3 và Table 4)</em></p><blockquote><p><strong>[Sách]</strong> = dịch và giải nghĩa từ các trang bạn chụp. <strong>[Bổ sung]</strong> = phần mình gom lại hoặc liên hệ thêm, nên đối chiếu khi đọc tiếp.</p></blockquote><hr><h2 id="_1-hai-bang-nay-noi-gi" tabindex="-1">1. Hai bảng này nói gì? <a class="header-anchor" href="#_1-hai-bang-nay-noi-gi" aria-label="Permalink to &quot;1. Hai bảng này nói gì?&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Bảng</th><th>Nội dung</th></tr></thead><tbody><tr><td><strong>Table 3</strong></td><td>Với mỗi hành tinh: (1) vị thần Babylon, (2) vị thần Hy Lạp, (3) ý nghĩa theo <strong>Vettius Valens</strong> (nhà chiêm tinh Hy Lạp thế kỷ 2)</td></tr><tr><td><strong>Table 4</strong></td><td>Ý nghĩa <strong>archetype hiện đại</strong> của 7 hành tinh</td></tr></tbody></table><p>Tác giả kết luận ngay dưới bảng: <em>&quot;Các ý nghĩa truyền thống khác nhau nhưng cũng chồng lấp nhau, và các ý nghĩa hiện đại hơn được gán cho hành tinh từ góc nhìn archetype.&quot;</em> Nghĩa là: truyền thống cổ liệt kê <strong>rất nhiều</strong> chủ đề cụ thể (con người, nghề, sự kiện), còn archetype hiện đại <strong>gom lại thành một hình mẫu</strong> dễ nhớ.</p><p><strong>Cách đọc 3 cột Babylon, Hy Lạp, Valens:</strong> thần thoại cho biết <strong>hình ảnh gốc</strong> của hành tinh, ý nghĩa Valens là <strong>danh sách chủ đề</strong> mà người xưa gán cho hành tinh đó khi xem lá số.</p><hr><h2 id="_2-tung-hanh-tinh" tabindex="-1">2. Từng hành tinh <a class="header-anchor" href="#_2-tung-hanh-tinh" aria-label="Permalink to &quot;2. Từng hành tinh&quot;">​</a></h2><h3 id="sun" tabindex="-1">Sun <a class="header-anchor" href="#sun" aria-label="Permalink to &quot;Sun&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>Nội dung</th></tr></thead><tbody><tr><td><strong>Babylon</strong></td><td><strong>Shamash</strong>: thần công lý, bói toán, lời thề, đĩa mặt trời tỏa tia nắng</td></tr><tr><td><strong>Hy Lạp</strong></td><td><strong>Hēlios</strong>: thần thấy tất cả, rực rỡ (&quot;Phoebus&quot;), nhân chứng cho lời thề, lái cỗ xe mặt trời qua bầu trời (được thờ ở Kos và Rhodes). <strong>Apollō</strong>: thần bói toán, chữa bệnh và âm nhạc</td></tr><tr><td><strong>Ý nghĩa theo Valens</strong></td><td>Ánh sáng của trí tuệ, cơ quan nhận thức của linh hồn, chức vị vua chúa, người có danh tiếng cao, óc phán đoán, vương miện chức vụ, lãnh đạo được lòng dân, người cha, đỉnh cao của vận may</td></tr><tr><td><strong>Archetype hiện đại</strong></td><td><strong>Leader, illuminator</strong> (người lãnh đạo, người soi sáng)</td></tr></tbody></table><h3 id="moon" tabindex="-1">Moon <a class="header-anchor" href="#moon" aria-label="Permalink to &quot;Moon&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>Nội dung</th></tr></thead><tbody><tr><td><strong>Babylon</strong></td><td><strong>Sin</strong>: thần trí tuệ, người đo thời gian</td></tr><tr><td><strong>Hy Lạp</strong></td><td>Ba nữ thần theo <strong>pha trăng</strong>: <strong>Selēnē</strong> (trăng tròn, canh giấc ngủ người phàm), <strong>Artemis</strong> (trăng non, sinh nở, muông thú, săn bắn), <strong>Hekatē</strong> (trăng khuyết/giảm sáng, ngã tư đường, cõi âm)</td></tr><tr><td><strong>Ý nghĩa theo Valens</strong></td><td>Sự phản chiếu ánh sáng Sun, sự sống, thân thể, người mẹ, sự thụ thai, hoàng hậu, những chuyến đi lang thang, hôn nhân hợp pháp, việc nhà, tài sản, tụ họp đám đông, gia đình, tàu thuyền, thu và chi</td></tr><tr><td><strong>Archetype hiện đại</strong></td><td><strong>Mother, caretaker</strong> (người mẹ, người chăm sóc)</td></tr></tbody></table><h3 id="mercury" tabindex="-1">Mercury <a class="header-anchor" href="#mercury" aria-label="Permalink to &quot;Mercury&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>Nội dung</th></tr></thead><tbody><tr><td><strong>Babylon</strong></td><td><strong>Nebu</strong>: thần ghi chép (scribe), thương mại, người viết ra số phận, nguồn trí tuệ con người</td></tr><tr><td><strong>Hy Lạp</strong></td><td><strong>Hermēs</strong>: sứ giả có cánh của Zeus, thần bảo hộ chữ viết và khoa học (đặc biệt toán và thiên văn), thương mại, du hành, thể thao, may mắn. Là <strong>psychopomp</strong> (người dẫn linh hồn xuống cõi âm) và là thần bảo hộ kẻ trộm</td></tr><tr><td><strong>Ý nghĩa theo Valens</strong></td><td>Thư từ, việc giáo dục con cái, thương mại, tranh luận, lời nói, anh em, tuổi trẻ, trộm cắp, người ban trí tuệ lý thuyết và thực tiễn, thầy đoán điềm (augurs), người giải mộng, luật sư, nhà hùng biện, triết gia, người xây đền, người quan sát bầu trời</td></tr><tr><td><strong>Archetype hiện đại</strong></td><td><strong>Messenger, trickster</strong> (sứ giả, kẻ lanh lợi tinh nghịch)</td></tr></tbody></table><h3 id="venus" tabindex="-1">Venus <a class="header-anchor" href="#venus" aria-label="Permalink to &quot;Venus&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>Nội dung</th></tr></thead><tbody><tr><td><strong>Babylon</strong></td><td><strong>Innana/Ishtar</strong>: nữ thần tình yêu khi là <strong>sao Hôm</strong>, nữ thần sự màu mỡ của đất đai, và <strong>nữ thần chiến tranh khi là sao Mai</strong></td></tr><tr><td><strong>Hy Lạp</strong></td><td><strong>Aphroditē</strong>: nữ thần tình yêu, sắc đẹp, ham muốn tình dục, khoái lạc</td></tr><tr><td><strong>Ý nghĩa theo Valens</strong></td><td>Ham muốn, tình yêu nhục dục, nghệ thuật, trang sức vàng, lễ hội tiệc tùng, đá quý, âm nhạc, tình bạn, tậu sắm đồ đạc của cải, đám cưới, hội họa, hòa giải theo hướng tốt</td></tr><tr><td><strong>Archetype hiện đại</strong></td><td><strong>Lover</strong> (người yêu). Ở đoạn trước (note về Venus) tác giả còn gọi là &quot;Lover and Harmonizer&quot;</td></tr></tbody></table><h3 id="mars" tabindex="-1">Mars <a class="header-anchor" href="#mars" aria-label="Permalink to &quot;Mars&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>Nội dung</th></tr></thead><tbody><tr><td><strong>Babylon</strong></td><td><strong>Nergal</strong>: thần cõi âm, sốt, dịch bệnh; được đồng nhất với <strong>Erra</strong>, thần chiến tranh</td></tr><tr><td><strong>Hy Lạp</strong></td><td><strong>Arēs</strong>: thần chiến tranh, sự tàn bạo, cơn thịnh nộ, người bảo hộ binh lính</td></tr><tr><td><strong>Ý nghĩa theo Valens</strong></td><td>Bạo lực, chiến tranh, ngoại tình, cướp bóc, giận dữ, đánh nhau, kẻ thù, đổ máu, sắt, tướng lĩnh, chiến binh, hủy hoại phụ nữ, mất mát, trục xuất, quan hệ tình dục, rạn nứt tình bạn, giết người, bị giam cầm</td></tr><tr><td><strong>Archetype hiện đại</strong></td><td><strong>Warrior</strong> (chiến binh)</td></tr></tbody></table><h3 id="jupiter" tabindex="-1">Jupiter <a class="header-anchor" href="#jupiter" aria-label="Permalink to &quot;Jupiter&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>Nội dung</th></tr></thead><tbody><tr><td><strong>Babylon</strong></td><td><strong>Marduk</strong>: đánh bại con rồng Tiamat, thiết lập trật tự và tổ chức trong vũ trụ, người bảo vệ công lý và luật pháp, chủ trì hội đồng 6 vị thần hành tinh còn lại, quyết định số phận con người</td></tr><tr><td><strong>Hy Lạp</strong></td><td><strong>Zeus</strong>: đánh bại con rồng Typhoeus, thiết lập trật tự trong vũ trụ, thủ lĩnh các vị thần, người bảo vệ công lý và luật pháp, người bảo hộ quốc gia, thần trí tuệ, hiện ra qua sấm sét, điều khiển số phận con người</td></tr><tr><td><strong>Ý nghĩa theo Valens</strong></td><td>Sinh con, tình yêu nhục dục, liên minh, tri thức, sự dồi dào, công lý, quyền tối thượng, hòa giải tranh chấp, xác nhận/bảo đảm điều tốt, tình bạn với người có địa vị lớn, ân huệ lớn, tự do, được giải thoát khỏi điều xấu, sự tín nhiệm (điều được ủy thác), thừa kế</td></tr><tr><td><strong>Archetype hiện đại</strong></td><td><strong>Sage, priest, wise man</strong> (hiền triết, thầy tế, người thông thái)</td></tr></tbody></table><h3 id="saturn" tabindex="-1">Saturn <a class="header-anchor" href="#saturn" aria-label="Permalink to &quot;Saturn&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>Nội dung</th></tr></thead><tbody><tr><td><strong>Babylon</strong></td><td><strong>Ninurta</strong>: thần chiến tranh và nông nghiệp, chúa tể của Trái Đất, điều tiết thủy lợi, thần bệnh tật và cái chết</td></tr><tr><td><strong>Hy Lạp</strong></td><td><strong>Kronos</strong>: Cha Thời Gian (Father Time), cai quản tuổi già và cái chết, thần nông nghiệp</td></tr><tr><td><strong>Ý nghĩa theo Valens</strong></td><td>Cô độc, gian dối, khổ sở, hành động bạo lực, trạng thái suy sụp u uất, hình phạt kéo dài, nước mắt, bị buộc tội, che giấu, bị giam cầm, không con, mồ côi, người lao động và nông dân, quyền trên đất đai, người thu thuế và hải quan, việc làm cưỡng bức</td></tr><tr><td><strong>Archetype hiện đại</strong></td><td><strong>Elder</strong> (bậc trưởng lão)</td></tr></tbody></table><hr><h2 id="_3-bang-tom-tat-đe-tra-nhanh" tabindex="-1">3. Bảng tóm tắt (để tra nhanh) <a class="header-anchor" href="#_3-bang-tom-tat-đe-tra-nhanh" aria-label="Permalink to &quot;3. Bảng tóm tắt (để tra nhanh)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Hành tinh</th><th>Thần Hy Lạp</th><th>Archetype hiện đại</th><th>Từ khóa Valens dễ nhớ</th></tr></thead><tbody><tr><td>Sun</td><td>Hēlios, Apollō</td><td>Leader, illuminator</td><td>Trí tuệ, vua chúa, danh tiếng, cha</td></tr><tr><td>Moon</td><td>Selēnē, Artemis, Hekatē</td><td>Mother, caretaker</td><td>Thân thể, mẹ, thụ thai, gia đình, thu chi</td></tr><tr><td>Mercury</td><td>Hermēs</td><td>Messenger, trickster</td><td>Lời nói, thư từ, thương mại, luật sư, anh em</td></tr><tr><td>Venus</td><td>Aphroditē</td><td>Lover</td><td>Ham muốn, nghệ thuật, tiệc tùng, tình bạn, đám cưới</td></tr><tr><td>Mars</td><td>Arēs</td><td>Warrior</td><td>Bạo lực, chiến tranh, tướng lĩnh, kẻ thù, mất mát</td></tr><tr><td>Jupiter</td><td>Zeus</td><td>Sage, priest, wise man</td><td>Con cái, công lý, dồi dào, thừa kế, tình bạn quyền quý</td></tr><tr><td>Saturn</td><td>Kronos</td><td>Elder</td><td>Cô độc, giam cầm, nông dân, tuổi già, trì hoãn kéo dài</td></tr></tbody></table><hr><h2 id="_4-nhung-đieu-đang-chu-y-bo-sung-minh-gom-tu-bang" tabindex="-1">4. Những điều đáng chú ý [Bổ sung, mình gom từ bảng] <a class="header-anchor" href="#_4-nhung-đieu-đang-chu-y-bo-sung-minh-gom-tu-bang" aria-label="Permalink to &quot;4. Những điều đáng chú ý [Bổ sung, mình gom từ bảng]&quot;">​</a></h2><h3 id="a-mot-hanh-tinh-co-the-co-nhieu-guong-mat" tabindex="-1">a) Một hành tinh có thể có nhiều &quot;gương mặt&quot; <a class="header-anchor" href="#a-mot-hanh-tinh-co-the-co-nhieu-guong-mat" aria-label="Permalink to &quot;a) Một hành tinh có thể có nhiều &quot;gương mặt&quot;&quot;">​</a></h3><ul><li><strong>Moon</strong> có 3 nữ thần theo pha trăng: Selēnē (trăng tròn), Artemis (trăng non), Hekatē (trăng giảm sáng). Nối với mục &quot;lunar phases&quot; trong bảng 3 tầng vũ trụ ở đầu sách: pha trăng không chỉ là chuyện thiên văn mà gắn với hình tượng khác nhau.</li><li><strong>Venus</strong> có hai mặt ở Babylon: sao <strong>Hôm</strong> là tình yêu, sao <strong>Mai</strong> là chiến tranh. Nối với oriental/occidental (xem <code>venus.md</code>): Venus mọc trước Sun được coi là chủ động, mạnh mẽ hơn. Mình nối ý này từ kiến thức chung, nên hãy đối chiếu với chương solar phase.</li><li><strong>Sun</strong> có hai thần: Hēlios (thấy tất cả, lái cỗ xe mặt trời) và Apollō (bói toán, chữa bệnh, âm nhạc).</li></ul><h3 id="b-cung-mot-chu-đe-xuat-hien-o-nhieu-hanh-tinh" tabindex="-1">b) Cùng một chủ đề xuất hiện ở nhiều hành tinh <a class="header-anchor" href="#b-cung-mot-chu-đe-xuat-hien-o-nhieu-hanh-tinh" aria-label="Permalink to &quot;b) Cùng một chủ đề xuất hiện ở nhiều hành tinh&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Chủ đề</th><th>Hành tinh liên quan (theo bảng Valens)</th></tr></thead><tbody><tr><td>Cha, mẹ</td><td>Sun: người cha. Moon: người mẹ</td></tr><tr><td>Con cái</td><td>Moon: thụ thai. Mercury: giáo dục con cái. Jupiter: sinh con. Saturn: không con</td></tr><tr><td>Hôn nhân, tình yêu</td><td>Moon: hôn nhân hợp pháp. Venus: tình yêu nhục dục, đám cưới. Jupiter: tình yêu nhục dục. Mars: ngoại tình, quan hệ tình dục</td></tr><tr><td>Bạn bè</td><td>Venus: tình bạn. Jupiter: tình bạn với người quyền quý. Mars: rạn nứt tình bạn</td></tr><tr><td>Công lý, luật</td><td>Sun: óc phán đoán. Jupiter: công lý, hòa giải tranh chấp. Mercury: luật sư, nhà hùng biện. Saturn: bị buộc tội. Mars: kẻ thù</td></tr><tr><td>Quyền lực, địa vị</td><td>Sun: chức vị vua chúa, danh tiếng. Moon: hoàng hậu. Jupiter: quyền tối thượng. Saturn: quyền trên đất đai. Mars: tướng lĩnh</td></tr><tr><td>Tiền bạc, tài sản</td><td>Moon: tài sản, thu chi. Venus: tậu sắm của cải, trang sức. Jupiter: dồi dào, thừa kế. Saturn: người thu thuế</td></tr><tr><td>Tri thức, lời nói</td><td>Sun: ánh sáng trí tuệ. Mercury: lời nói, thư từ, triết gia. Jupiter: tri thức</td></tr><tr><td>Nghề nghiệp</td><td>Mercury: luật sư, triết gia, người xây đền. Mars: tướng lĩnh, chiến binh. Saturn: nông dân, lao động. Venus: nghệ thuật, hội họa, âm nhạc</td></tr><tr><td>Bạo lực, giam cầm</td><td>Mars: bạo lực, giết người, giam cầm. Saturn: hành động bạo lực, giam cầm, hình phạt kéo dài</td></tr></tbody></table><p><strong>Ý nghĩa thực tế:</strong> khi muốn đọc một chủ đề (ví dụ con cái, hôn nhân), không chỉ có một hành tinh liên quan. Hãy xem <strong>hành tinh nào là chủ house</strong> của chủ đề đó, rồi dùng bảng này để biết các hành tinh khác &quot;thêm gì&quot; vào câu chuyện. Đây là lý do sách nói các ý nghĩa &quot;chồng lấp&quot;.</p><h3 id="c-moi-hanh-tinh-đeu-co-mat-tot-va-mat-xau-trong-cung-mot-danh-sach" tabindex="-1">c) Mỗi hành tinh đều có mặt tốt và mặt xấu trong cùng một danh sách <a class="header-anchor" href="#c-moi-hanh-tinh-đeu-co-mat-tot-va-mat-xau-trong-cung-mot-danh-sach" aria-label="Permalink to &quot;c) Mỗi hành tinh đều có mặt tốt và mặt xấu trong cùng một danh sách&quot;">​</a></h3><ul><li><strong>Mars</strong>: &quot;tướng lĩnh, chiến binh&quot; (tốt) và &quot;giết người, giam cầm&quot; (xấu).</li><li><strong>Saturn</strong>: &quot;nông dân, quyền trên đất đai&quot; (trung tính/tốt) và &quot;giam cầm, nước mắt, suy sụp&quot; (xấu).</li><li><strong>Mercury</strong>: &quot;triết gia, người xây đền, người giải mộng&quot; (tốt) và &quot;trộm cắp&quot; (xấu), khớp với Hermēs vừa là sứ giả vừa là thần bảo hộ kẻ trộm.</li></ul><p>Đây chính là nguyên tắc condition đã học: <strong>cùng một hành tinh, condition tốt thì biểu hiện mặt tốt, condition xấu thì biểu hiện mặt xấu</strong>.</p><h3 id="d-benefic-va-malefic-hien-ra-ro-trong-ngon-ngu-cua-bang" tabindex="-1">d) Benefic và malefic hiện ra rõ trong ngôn ngữ của bảng <a class="header-anchor" href="#d-benefic-va-malefic-hien-ra-ro-trong-ngon-ngu-cua-bang" aria-label="Permalink to &quot;d) Benefic và malefic hiện ra rõ trong ngôn ngữ của bảng&quot;">​</a></h3><p>Jupiter và Venus dùng nhiều từ tích cực (dồi dào, công lý, tự do, hòa giải, lễ hội). Mars và Saturn dùng nhiều từ tiêu cực hơn (giam cầm, mất mát, nước mắt, trục xuất). Đúng với việc Jupiter, Venus là benefic và Mars, Saturn là malefic. Nhưng cả bốn đều có ít nhất vài ý trung tính hoặc tốt, nên không có hành tinh nào &quot;chỉ xấu&quot; hay &quot;chỉ tốt&quot;.</p><h3 id="e-archetype-hien-đai-la-ban-thu-gon" tabindex="-1">e) Archetype hiện đại là bản thu gọn <a class="header-anchor" href="#e-archetype-hien-đai-la-ban-thu-gon" aria-label="Permalink to &quot;e) Archetype hiện đại là bản thu gọn&quot;">​</a></h3><p>Table 4 gom danh sách dài của Valens thành một hình mẫu. Ví dụ Mars chỉ còn &quot;Warrior&quot;, nhưng nghĩa cổ có cả &quot;ngoại tình, cướp bóc, giam cầm&quot;. Mercury &quot;Messenger, trickster&quot; gần với Hermēs. Cái được: dễ nhớ, dễ nói với người đối diện. Cái mất: những chủ đề cụ thể mà truyền thống dùng để đọc sự kiện (nghề, người, tình huống).</p><p>Gợi ý: học archetype trước để nắm &quot;tinh thần&quot; của hành tinh, rồi dùng danh sách Valens để đọc cụ thể hơn.</p><hr><h2 id="_5-khi-xem-la-so-cho-nguoi-khac-bo-sung" tabindex="-1">5. Khi xem lá số cho người khác [Bổ sung] <a class="header-anchor" href="#_5-khi-xem-la-so-cho-nguoi-khac-bo-sung" aria-label="Permalink to &quot;5. Khi xem lá số cho người khác [Bổ sung]&quot;">​</a></h2><ul><li>Các từ như <strong>ngoại tình, giết người, hủy hoại phụ nữ, trộm cắp, giam cầm</strong> là <strong>ngôn ngữ lịch sử</strong> của sách, mô tả những gì người xưa gắn với hành tinh. <strong>Đừng nói thẳng</strong> với người đối diện như thể đó là điều sẽ xảy ra với họ.</li><li>Nên chuyển sang mức xu hướng, ví dụ: Mars xấu → &quot;dễ nóng, dễ xung đột, cần chỗ xả năng lượng&quot; (không phải &quot;bạn sẽ bạo lực&quot;).</li><li>Dùng archetype (Table 4) làm lối vào, và dùng danh sách Valens để gợi ý chủ đề cụ thể rồi <strong>hỏi người đối diện</strong> xem có khớp với đời sống của họ không.</li><li>Một ý nghĩa xuất hiện trong bảng <strong>không có nghĩa nó sẽ xảy ra</strong>, mà là hành tinh đó có thể liên quan tới chủ đề đó. Việc nó tốt hay xấu phụ thuộc condition (sect, dignity, phase, aspect, house), như các note trước.</li><li>Đúng tinh thần note về Fate và Free Will: lá số mô tả hoàn cảnh và tiền đề, không ép buộc hành động.</li></ul><hr><h2 id="_6-tu-vung-kho-trong-hai-bang" tabindex="-1">6. Từ vựng khó trong hai bảng <a class="header-anchor" href="#_6-tu-vung-kho-trong-hai-bang" aria-label="Permalink to &quot;6. Từ vựng khó trong hai bảng&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tiếng Anh</th><th>Tiếng Việt</th></tr></thead><tbody><tr><td>Psychopomp</td><td>Người dẫn linh hồn xuống cõi âm</td></tr><tr><td>Augurs</td><td>Thầy đoán điềm</td></tr><tr><td>Plundering</td><td>Cướp bóc</td></tr><tr><td>Adultery</td><td>Ngoại tình</td></tr><tr><td>Sovereignty</td><td>Quyền tối thượng</td></tr><tr><td>Mediation of disputes</td><td>Hòa giải tranh chấp</td></tr><tr><td>Deliverance from evils</td><td>Được giải thoát khỏi điều xấu</td></tr><tr><td>Trusts</td><td>Sự tín nhiệm, điều được ủy thác</td></tr><tr><td>Concealments</td><td>Che giấu</td></tr><tr><td>Captivity</td><td>Bị giam cầm</td></tr><tr><td>Banishment</td><td>Bị trục xuất</td></tr><tr><td>Breaches of friends</td><td>Rạn nứt tình bạn</td></tr><tr><td>Crowns of office</td><td>Vương miện chức vụ (biểu tượng quyền lực)</td></tr><tr><td>Housekeeping</td><td>Việc nhà, quản gia</td></tr><tr><td>Receipts and expenditures</td><td>Thu và chi</td></tr><tr><td>Archetype</td><td>Hình mẫu nguyên mẫu</td></tr><tr><td>Trickster</td><td>Kẻ lanh lợi tinh nghịch (hay lừa gạt để đùa)</td></tr></tbody></table><hr><h2 id="_7-đieu-can-kiem-chung" tabindex="-1">7. Điều cần kiểm chứng <a class="header-anchor" href="#_7-đieu-can-kiem-chung" aria-label="Permalink to &quot;7. Điều cần kiểm chứng&quot;">​</a></h2><ul><li>Mình dịch sát nghĩa từ các trang bạn chụp, nhưng một số từ có nhiều cách hiểu (ví dụ &quot;trusts&quot;, &quot;depressions&quot;, &quot;augurs&quot;). Nếu cần dịch chính xác cho nội dung công khai, hãy đối chiếu với bản gốc.</li><li>Phần mục 4 và mục 5 là cách mình gom và diễn giải thêm, không phải lập luận của tác giả.</li><li>Mình không tra cứu được nguồn bên ngoài nên các liên hệ với oriental/occidental của Venus nên được đối chiếu với chương solar phase của sách.</li></ul>',51)])])}const m=n(a,[["render",o]]);export{l as __pageData,m as default};
